/**
 * Normalizes markdown content to ensure GitHub Flavored Markdown (GFM)
 * tables and formatting render properly even when generated by LLMs with
 * squashed newlines or missing boundary spacing.
 */
export function normalizeMarkdown(content) {
  if (!content || typeof content !== 'string') return '';

  const lines = content.split('\n');
  const output = [];
  let inCode = false;
  let inTable = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Preserve code blocks without modification
    if (trimmed.startsWith('```')) {
      inCode = !inCode;
      output.push(line);
      continue;
    }

    if (inCode) {
      output.push(line);
      continue;
    }

    // If a line contains squashed table rows joined with || or | |, split them
    if (trimmed.startsWith('|') && (trimmed.includes('||') || trimmed.includes('| |'))) {
      const expandedLines = line.replace(/\|\s*\|/g, '|\n|').split('\n');
      for (let j = 0; j < expandedLines.length; j++) {
        const expLine = expandedLines[j];
        const expTrimmed = expLine.trim();
        const isRow = expTrimmed.startsWith('|') && expTrimmed.endsWith('|');

        if (isRow && !inTable) {
          if (output.length > 0 && output[output.length - 1].trim() !== '') {
            output.push('');
          }
          inTable = true;
        } else if (!isRow && inTable) {
          if (output.length > 0 && output[output.length - 1].trim() !== '') {
            output.push('');
          }
          inTable = false;
        }

        output.push(expLine);
      }
      continue;
    }

    const isTableRow = trimmed.startsWith('|') && trimmed.endsWith('|');
    if (isTableRow && !inTable) {
      if (output.length > 0 && output[output.length - 1].trim() !== '') {
        output.push('');
      }
      inTable = true;
    } else if (!isTableRow && inTable) {
      if (output.length > 0 && output[output.length - 1].trim() !== '') {
        output.push('');
      }
      inTable = false;
    }

    output.push(line);
  }

  return output.join('\n');
}
